document.addEventListener('DOMContentLoaded', function() {
  // Wait for echarts4r to initialize
  setTimeout(function() {
    setupChartAnimation();
  }, 1000);
});

function setupChartAnimation() {
  const observeCharts = new IntersectionObserver((entries) => {
    entries.forEach(entry => {
      if (entry.isIntersecting) {
        entry.target.classList.add('visible');

        // echarts container
        const echartsDiv = entry.target.querySelector('div[id^="htmlwidget-"]') || 
                          entry.target.querySelector('.echarts4r') ||
                          entry.target.querySelector('.html-widget');

        if (echartsDiv) {
          const chart = echarts.getInstanceByDom(echartsDiv);
          if (chart) {
            // Clear the chart and redraw with animation after the container becomes visible
            setTimeout(() => {
              const currentOption = chart.getOption();
              chart.clear();

              // Re-set the option with animation enabled
              chart.setOption(currentOption, {
                notMerge: true,
                lazyUpdate: false,
                silent: false
              });
            }, 10); // Delay to ensure visibility transition has started
          }
        }

        // Only animate once
        observeCharts.unobserve(entry.target);
      }
    });
  }, { 
    threshold: 0.1,
    rootMargin: '0px 0px -20px 0px'
  });

  // Initially hide all charts and set up observation
  document.querySelectorAll('.chart-container').forEach(el => {
    const echartsDiv = el.querySelector('div[id^="htmlwidget-"]') || 
                      el.querySelector('.echarts4r') ||
                      el.querySelector('.html-widget');

    if (echartsDiv) {
      const chart = echarts.getInstanceByDom(echartsDiv);
      if (chart) {
        // Disable initial animation by clearing and redrawing without animation
        const currentOption = chart.getOption();
        chart.clear();
        chart.setOption(currentOption, {
          notMerge: true,
          lazyUpdate: false,
          silent: true // Disable animation for initial draw
        });
      }
    }

    observeCharts.observe(el);
  });
}
</script>
```

## <i class="bi bi-building"></i> Our Research Centre

::: {.grid}

::: {.g-col-7}
The Canadian Centre for Welding and Joining (CCWJ) is one of the world's largest university initiatives in welding with a global reputation reflected in multiple awards, such as the “Image of Welding Award” awarded by the American Welding Society as a leading education institution in 2013.

The CCWJ’s $5.5M facility houses all forms of arc welding, a 9 kW laser, and several robots. Diagnostic tools include high speed cameras, laser lighting, a specialized thermal camera, wavelength spectrometer, and data acquisition. Characterization capabilities include hardness mapping, surface profilometry, instrumented impact, hydrogen, oxygen, and nitrogen testing, dilatometry, and metallography. Centralized facilities at the UofA also provide access to high end electron microscopy and composition analysis tools. Tools of analysis at the CCWJ include latest generation weld modeling software such as VRWeld, Simufact, and Transweld, and general purpose modeling software such as Comsol and Matlab.
:::

